// AXI Skid buffer where all ports are driven or received by a flop
module gaxi_skid_buffer_async #(
    parameter fifo_mem_t MEM_STYLE = FIFO_AUTO,
    parameter int REGISTERED = 0,  // 0 = mux mode, 1 = flop mode
    parameter int DATA_WIDTH    = 32,
    parameter int DEPTH         = 2,
    // Pointer CDC encoding, forwarded to the internal gaxi_fifo_async.
    //   0 = Gray (default)  -- requires a power-of-2 DEPTH
    //   1 = Johnson         -- any DEPTH, odd included
    // Must be exposed here: a wrapper that hides it cannot be built at a
    // non-power-of-2 depth, because the inner FIFO rejects that under Gray.
    parameter int USE_JOHNSON   = 0,
    parameter int N_FLOP_CROSS  = 2,
    parameter int DW = DATA_WIDTH
) (
    // Global Clock and Reset
    input  logic          axi_wr_aclk,
    input  logic          axi_wr_aresetn,
    input  logic          axi_rd_aclk,
    input  logic          axi_rd_aresetn,

    // input side
    input  logic          wr_valid,
    output logic          wr_ready,
    input  logic [DW-1:0] wr_data,

    // output side
    output logic          rd_valid,
    input  logic          rd_ready,
    output logic [DW-1:0] rd_data
);

    logic           r_xfer_valid;
    logic           r_xfer_ready;
    logic [DW-1:0]  r_xfer_data;

    // Instantiate the axi_skid_buffer module
    gaxi_skid_buffer #(
        .DATA_WIDTH   (DW)
    ) inst_gaxi_skid_buffer (
        .axi_aclk   (axi_wr_aclk),
        .axi_aresetn(axi_wr_aresetn),
        .wr_valid   (wr_valid),
        .wr_ready   (wr_ready),
        .wr_data    (wr_data),
        .rd_valid   (r_xfer_valid),
        .rd_ready   (r_xfer_ready),
        .rd_data    (r_xfer_data),
        .rd_count   (),
        .count     ()
    );

    // Instantiate the axi_fifo_async module
    gaxi_fifo_async #(
        .MEM_STYLE       (MEM_STYLE),
        .DATA_WIDTH      (DW),
        .DEPTH           (DEPTH),
        .USE_JOHNSON     (USE_JOHNSON),
        .N_FLOP_CROSS    (N_FLOP_CROSS),
        .ALMOST_WR_MARGIN(1),
        .ALMOST_RD_MARGIN(1),
        .REGISTERED      (REGISTERED)
    ) inst_gaxi_fifo_async (
        .axi_wr_aclk   (axi_wr_aclk),
        .axi_wr_aresetn(axi_wr_aresetn),
        .axi_rd_aclk   (axi_rd_aclk),
        .axi_rd_aresetn(axi_rd_aresetn),
        .wr_valid      (r_xfer_valid),
        .wr_ready      (r_xfer_ready),
        .wr_data       (r_xfer_data),
        .rd_ready      (rd_ready),
        .rd_valid      (rd_valid),
        .rd_data       (rd_data)
    );

endmodule : gaxi_skid_buffer_async

module high_speed_in_bus (
    input clk,
    input rst,

    input  data_required,
    output data_available, // If data_available is high and rst is low, then you can read the data from the in_data bus.

    input request,
    output reg acknowledge
);
    wire request_sync;

    double_flop_synchronizer double_flop_synchronizer_request (
        .clk(clk),
        .rst(rst),
        .enable(1'b1),
        .in(request),
        .out(request_sync)
    );

    assign data_available = ~acknowledge & request_sync & data_required;

    // Acknowledge logic. We assume that when acknowledge is high, the data is read from the in_data bus by another component
    // in the same clock cycle. Therefore, we can set acknowledge to low in the next clock cycle.
    always @(posedge clk, posedge rst) begin
        if (rst) acknowledge <= 1'b0;
        else if (data_available) acknowledge <= 1'b1;
        else if (acknowledge && !request_sync) acknowledge <= 1'b0;
    end

endmodule

module high_speed_out_bus #(
    parameter integer HIGH_SPEED_OUT_PINS = 8,
    parameter integer SENT_COUNTER_BIT_WIDTH = 4
) (
    input clk,
    input rst,

    input in_idle,
    input sending,
    input will_stop_sending, // next_state != `SENDING

    input data_ready_for_sending,

    input [SENT_COUNTER_BIT_WIDTH-1:0] num_sends,

    input [HIGH_SPEED_OUT_PINS-1:0] in,

    output reg request,
    input acknowledge,

    output reg [HIGH_SPEED_OUT_PINS-1:0] out,
    output reg [SENT_COUNTER_BIT_WIDTH-1:0] sent_counter,

    output done_sending
);
    wire acknowledge_sync;

    double_flop_synchronizer double_flop_synchronizer_acknowledge (
        .clk(clk),
        .rst(rst),
        .enable(1'b1),
        .in(acknowledge),
        .out(acknowledge_sync)
    );

    assign done_sending = acknowledge_sync & !request & (sent_counter == num_sends);

    always @(posedge clk) begin
        // TODO: is a reset every idle cycle really necessary?
        if (in_idle) begin
            request <= 1'b0;
            out <= 0;
            sent_counter <= 0;
        end else if (sending && will_stop_sending) begin
            request <= 1'b0;
            sent_counter <= 0;
        end else if (sending && (sent_counter <= num_sends)) begin
            if (!acknowledge_sync && !request) begin
                if (data_ready_for_sending) begin
                    request <= 1'b1;
                    out <= in;
                end
            end else if (acknowledge_sync && request) begin
                request <= 1'b0;
                sent_counter <= sent_counter + 1;
            end
        end
    end
endmodule

